import { cx } from "@/lib/cx";

export function Segmented<T extends string>(props: {
  options: readonly { value: T; label: string }[];
  value: T;
  onChange: (value: T) => void;
  testIdPrefix?: string;
}) {
  return (
    <div role="radiogroup" className="inline-flex h-9 rounded-lg bg-panel-2 p-1 border border-line">
      {props.options.map((opt) => {
        const active = opt.value === props.value;
        return (
          <button
            key={opt.value}
            type="button"
            role="radio"
            aria-checked={active}
            data-testid={props.testIdPrefix ? props.testIdPrefix + opt.value : undefined}
            onClick={() => props.onChange(opt.value)}
            className={cx(
              "flex-1 rounded-md px-2.5 text-sm font-medium whitespace-nowrap transition",
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand",
              active
                ? "bg-panel text-ink shadow-sm ring-1 ring-line"
                : "text-muted hover:text-ink hover:bg-line",
            )}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}
import type { ButtonHTMLAttributes } from "react";
import { cx } from "@/lib/cx";

const VARIANTS = {
  primary: "bg-brand-fill text-white hover:brightness-110 border-transparent",
  secondary: "bg-panel text-ink border-line hover:bg-panel-2",
  ghost: "bg-transparent text-ink border-transparent hover:bg-panel-2",
  danger: "bg-panel text-danger border-line hover:bg-danger-soft",
} as const;

export function Button({
  variant = "secondary",
  size = "md",
  className,
  type = "button",
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: keyof typeof VARIANTS;
  size?: "sm" | "md";
}) {
  return (
    <button
      type={type}
      className={cx(
        "inline-flex items-center justify-center gap-1.5 rounded-lg border font-medium transition",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand",
        "disabled:cursor-not-allowed disabled:opacity-50",
        size === "sm" ? "h-7 px-2.5 text-xs" : "h-9 px-3.5 text-sm",
        VARIANTS[variant],
        className,
      )}
      {...rest}
    />
  );
}
